import {C,blackHole} from './physics.mjs';
export const TEMPERATURE_RANGE=Object.freeze({minPositive:.001,max:1e12});
export function kelvinToCelsius(k){if(!Number.isFinite(k)||k<0)throw new RangeError('Kelvin muss endlich und ≥ 0 sein');return k-273.15}
export function celsiusToKelvin(c){if(!Number.isFinite(c)||c< -273.15)throw new RangeError('Unterhalb des absoluten Nullpunkts');return c+273.15}
export function logTemperature(k){if(!Number.isFinite(k)||k<TEMPERATURE_RANGE.minPositive||k>TEMPERATURE_RANGE.max)throw new RangeError('Logskala: 0,001 bis 10¹² K');return (Math.log10(k)+3)/15}
export function temperatureAt(f){if(!Number.isFinite(f)||f<0||f>1)throw new RangeError('Skalenposition: 0 bis 1');return 10**(-3+15*f)}
export function schwarzschild(m){if(!Number.isFinite(m)||m<1||m>1e41)throw new RangeError('Masse: 1 bis 10⁴¹ kg');const b=blackHole(m);return {mass:m,horizon:b.radius,photonSphere:1.5*b.radius,isco:3*b.radius,hawking:b.temperature}}
export const EXAMPLES=Object.freeze({white:Object.freeze({name:'Weißer Zwerg',mass:.6*C.sun,radius:7e6,color:'#c5dcff',assumption:'Illustratives Beispiel: 0,6 M☉ und 7000 km Radius; keine universelle Masse-Radius-Kurve.'}),neutron:Object.freeze({name:'Neutronenstern',mass:1.4*C.sun,radius:12000,color:'#b3a1ff',assumption:'Illustratives Beispiel: 1,4 M☉ und 12 km Radius; keine festgelegte Zustandsgleichung, nicht jeder Neutronenstern ist ein Pulsar.'})});
export function compactObject(kind,m){if(kind==='blackhole'){const b=schwarzschild(m);return {kind,name:'Schwarzes Loch',mass:m,radius:b.horizon,density:null,color:'#f7bd89',assumption:'Schwarzschild-Loch: ungeladen, nicht rotierend. rₛ ist keine Materialoberfläche.',...b}}const b=EXAMPLES[kind];if(!b)throw new RangeError('Unbekannter Objekttyp');return {kind,...b,density:b.mass/(4*Math.PI*b.radius**3/3)}}
export function comparisonPosition(radius,mode,maxRadius,minRadius){if(![radius,maxRadius,minRadius].every(Number.isFinite)||minRadius<=0||maxRadius<minRadius||radius<minRadius||radius>maxRadius)throw new RangeError('Ungültiger Größenvergleich');if(mode==='linear')return radius/maxRadius;if(mode==='log')return maxRadius===minRadius?.5:Math.log(radius/minRadius)/Math.log(maxRadius/minRadius);throw new RangeError('Unbekannte Skala')}
